<template><section class="cost-page"><header class="cost-page-heading"><div><h2>گزارش و تحلیل هزینه</h2><p>هزینه‌های ثبت‌شده و هزینه تولید را در یک بازه مشخص بررسی کنید.</p></div></header><form class="cost-filter" @submit.prevent="load"><JalaliDatePicker v-model="filters.start_date" placeholder="از تاریخ"/><JalaliDatePicker v-model="filters.end_date" placeholder="تا تاریخ"/><select v-model="view"><option value="categories">دسته‌بندی هزینه</option><option value="products">محصول و تولید</option><option value="materials">قیمت فعلی مواد</option></select><button class="cost-primary" :disabled="loading">تهیه گزارش</button></form><div v-if="error" class="cost-notice" role="alert">{{error}} <button @click="load">تلاش مجدد</button></div><div class="report-summary"><article><span>کل هزینه ثبت‌شده</span><strong>{{money(dashboard.total_expenses)}}</strong></article><article><span>تعداد هزینه‌ها</span><strong>{{number(dashboard.expense_count)}} مورد</strong></article><article><span>هزینه تولیدهای تکمیل‌شده</span><strong>{{money(dashboard.completed_order_cost)}}</strong></article><article><span>هزینه سربار</span><strong>{{money(dashboard.overhead_total)}}</strong></article></div><section class="report-card" v-if="view==='categories'"><header><h3>هزینه بر اساس دسته‌بندی</h3></header><div v-for="row in dashboard.expense_by_category" :key="row.category_id" class="report-row"><span>{{row.category__name}}</span><strong>{{money(row.total)}}</strong><small>{{number(row.count)}} هزینه</small></div><p v-if="!dashboard.expense_by_category?.length">در این بازه هزینه‌ای ثبت نشده است.</p></section><section class="report-card" v-else-if="view==='products'"><header><h3>هزینه تولید محصولات</h3></header><div v-for="row in dashboard.production_costs" :key="row.id" class="report-row"><span>{{row.name}}</span><strong>{{money(row.expected_cost)}}</strong><small>هزینه واقعی: {{row.actual_unit_cost===null?'هنوز تولیدی ثبت نشده':money(row.actual_unit_cost)}} · اختلاف: {{row.variance===null?'—':money(row.variance)}}</small></div><p v-if="!dashboard.production_costs?.length">محصولی برای تحلیل وجود ندارد.</p></section><section class="report-card" v-else><header><h3>قیمت فعلی مواد اولیه</h3><small>این قیمت‌ها وابسته به بازه تاریخی نیستند.</small></header><div v-for="item in materials" :key="item.id" class="report-row"><span>{{item.name}}</span><strong>{{money(item.unit_cost)}}</strong><small>برای هر {{item.unit_display}}</small></div><p v-if="!materials.length">ماده اولیه‌ای ثبت نشده است.</p></section></section></template>
<script setup>import{onMounted,reactive,ref}from'vue';import API from'@/api/product-cost.api.js';import JalaliDatePicker from'@/components/cost/JalaliDatePicker.vue';import{costErrorMessage,formatCostNumber as number,formatMoney as money}from'@/utils/costControl';const loading=ref(false),error=ref(''),view=ref('categories'),materials=ref([]),filters=reactive({start_date:'',end_date:''}),dashboard=reactive({total_expenses:0,expense_count:0,completed_order_cost:0,overhead_total:0,expense_by_category:[],production_costs:[]});async function load(){loading.value=true;error.value='';try{const[data,ingredients]=await Promise.all([API.dashboard({...filters}),materials.value.length?Promise.resolve(materials.value):API.activeIngredients()]);Object.assign(dashboard,data);materials.value=ingredients}catch(cause){error.value=costErrorMessage(cause)}finally{loading.value=false}}onMounted(load)</script>
<style scoped>.report-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.report-summary article{display:grid;gap:5px;padding:14px;background:var(--surface);border:1px solid var(--border);border-radius:11px}.report-summary span{color:var(--muted);font-size:.72rem}.report-card{padding:16px;background:var(--surface);border:1px solid var(--border);border-radius:13px}.report-card>header{display:flex;justify-content:space-between;margin-bottom:8px}.report-card h3{margin:0;font-size:.95rem}.report-card header small,.report-card>p{color:var(--muted);font-size:.72rem}.report-row{display:grid;grid-template-columns:1fr auto;gap:4px;padding:11px 0;border-bottom:1px solid var(--border);font-size:.8rem}.report-row small{grid-column:1/-1;color:var(--muted)}@media(max-width:700px){.report-summary{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:430px){.report-summary{grid-template-columns:1fr}}</style>
